import * as React from "react";
import { ModalPortalProps } from "./ModalPortal";
export type { ModalSize, ModalCloseEvent } from "./ModalPortal";
export interface ModalProps extends ModalPortalProps {
    /**
     * If the modal is open.
     *
     * @default false
     */
    isOpen?: boolean;
}
/**
 * Modals focus the user’s attention on a single task in a window that sits on top of the page content.
 *
 * - {@link https://livingdesign.walmart.com/components/modal/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/modal/react/ React documentation}
 *
 * ### Actions
 *
 * The Modal accepts actions through the `actions` prop:
 *
 * ```tsx
 * <Modal
 *   actions={
 *     <ButtonGroup>
 *       <Button>Action1</Button>
 *       <Button>Action2</Button>
 *     </ButtonGroup>
 *   }
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 * >
 *   Content
 * </Modal>
 * ```
 *
 * ### Content
 *
 * The Modal accepts content through the `children` prop:
 *
 * ```tsx
 * <Modal
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 * >
 *   Content
 * </Modal>
 * ```
 *
 * ### Opening and closing
 *
 * The Modal is open based on the `isOpen` property. Add an `onClose` callback that configures `isOpen` state when the Modal requests to close.
 *
 * ```tsx
 * export default () => {
 *   const [isOpen, setIsOpen] = React.useState(false);
 *
 *   return (
 *     <>
 *       <Button onClick={() => setIsOpen(true)}>
 *         Open modal
 *       </Button>
 *
 *       <Modal
 *         isOpen={isOpen}
 *         onClose={() => setIsOpen(false)}
 *         title="Title"
 *       >
 *         Content
 *       </Modal>
 *     </>
 *   );
 * };
 * ```
 *
 * ### Size
 *
 * The Modal comes in three sizes. Set the size with the `size` prop:
 *
 * ```tsx
 * <Modal
 *   onClose={() => setIsOpen(false)}
 *   size="small"
 *   title="Title"
 * >
 *   Small
 * </Modal>
 *
 * <Modal
 *   onClose={() => setIsOpen(false)}
 *   size="medium"
 *   title="Title"
 * >
 *   Medium
 * </Modal>
 *
 * <Modal
 *   onClose={() => setIsOpen(false)}
 *   size="large"
 *   title="Title"
 * >
 *   Large
 * </Modal>
 * ```
 *
 * ### Title
 *
 * Set the title for the Modal with the `title` prop:
 *
 * ```tsx
 * <Modal
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 * >
 *   Modal
 * </Modal>
 * ```
 */
export declare const Modal: React.FunctionComponent<ModalProps>;
